<?php $title='Beranda';require __DIR__.'/includes/header.php';$b=$pdo->query("SELECT * FROM banners WHERE active=1 ORDER BY sort_order,id DESC LIMIT 5")->fetchAll();$cats=$pdo->query("SELECT * FROM categories ORDER BY sort_order,id DESC LIMIT 8")->fetchAll();$products=$pdo->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.featured=1 ORDER BY p.id DESC LIMIT 8")->fetchAll(); ?>
<section class="hero"><?php foreach($b as $i=>$x):?><div class="hero-slide <?=$i?'':'active'?>" style="background-image:linear-gradient(90deg,rgba(0,0,0,.65),rgba(0,0,0,.1)),url('<?=e($x['image'])?>')"><div><small><?=e($x['eyebrow'])?></small><h1><?=e($x['title'])?></h1><p><?=e($x['subtitle'])?></p><a class="btn" href="<?=e($x['button_url']?:'/produk.php')?>"><?=e($x['button_text']?:'Lihat Produk')?></a></div></div><?php endforeach;if(!$b):?><div class="hero-slide active"><div><small>ANIMO LABEL</small><h1>Label yang membuat brand Anda lebih berkesan.</h1><p>Produksi label dan printing custom untuk bisnis modern.</p><a class="btn" href="<?=e(wa())?>">Konsultasi WhatsApp</a></div></div><?php endif;?></section>
<section class="section"><div class="section-head"><div><small>KATEGORI</small><h2>Temukan solusi untuk kebutuhan brand Anda</h2></div><a href="/produk.php">Lihat semua →</a></div><div class="grid cats"><?php foreach($cats as $c):?><a class="card image-card" href="/produk.php?category=<?=$c['id']?>"><img src="<?=e(img($c['image']))?>"><span><?=e($c['name'])?></span></a><?php endforeach;?></div></section>
<section class="section soft"><div class="section-head"><div><small>PRODUK UNGGULAN</small><h2>Produk yang siap disesuaikan dengan kebutuhan Anda</h2></div></div><div class="grid products"><?php foreach($products as $p):?><article class="product"><img src="<?=e(img($p['image']))?>"><div><small><?=e($p['category_name'])?></small><h3><?=e($p['name'])?></h3><?php if($p['description']):?><p><?=e($p['description'])?></p><?php endif;if($p['price']!==''):?><strong><?=e($p['price'])?></strong><?php endif;?><a href="/produk-detail.php?id=<?=$p['id']?>">Lihat detail →</a></div></article><?php endforeach;?></div></section>
<section class="cta"><div><small>SIAP MULAI?</small><h2>Punya kebutuhan label custom?</h2><p>Konsultasikan ukuran, material, finishing, dan jumlah produksi Anda.</p></div><a class="btn" href="<?=e(wa())?>">Konsultasi Sekarang</a></section><?php require __DIR__.'/includes/footer.php';?>